using SmartiePaws.Inventory.Core.Enums.Sales;

namespace SmartiePaws.Inventory.Core.Entities.Sales;

/// <summary>
/// One sale transaction -- the receipt-level record, holding the totals for the whole
/// transaction. What was actually sold lives in <see cref="SaleLineItem"/>, one row per item on
/// the receipt.
/// </summary>
public class Sale
{
  /// <summary>
  /// Primary key. Generated by Postgres (<c>gen_random_uuid()</c>) on insert.
  /// </summary>
  public Guid Id { get; set; }

  /// <summary>
  /// Who bought this, if known. Nullable for anonymous/walk-in sales.
  /// </summary>
  public Guid? CustomerId { get; set; }

  /// <summary>
  /// Navigation to the customer. Only populated when explicitly requested.
  /// </summary>
  public Customer? Customer { get; set; }

  /// <summary>
  /// The timestamp the sale actually happened at (distinct from <see cref="CreatedAt"/>, in case
  /// a sale is ever entered after the fact).
  /// </summary>
  public DateTimeOffset SoldAt { get; set; }

  /// <summary>
  /// The sum of all line items' totals, before any sale-level discount or tax.
  /// </summary>
  public decimal Subtotal { get; set; }

  /// <summary>
  /// How a sale-wide discount (if any) is expressed: a percentage or a flat dollar amount.
  /// Nullable -- not every sale has a sale-level discount.
  /// </summary>
  public DiscountType? DiscountType { get; set; }

  /// <summary>
  /// The raw discount number paired with <see cref="DiscountType"/> (e.g. <c>10</c> meaning
  /// either "10%" or "$10" depending on the type).
  /// </summary>
  public decimal? DiscountValue { get; set; }

  /// <summary>
  /// The actual dollar amount the discount resolves to, computed once and stored, so historical
  /// totals never shift even if the discount calculation logic changes later.
  /// </summary>
  public decimal DiscountAmount { get; set; }

  /// <summary>
  /// The tax rate applied to this sale. Stored per-sale (not looked up from some global config)
  /// so old receipts stay accurate if the rate ever changes.
  /// </summary>
  public decimal TaxRate { get; set; }

  /// <summary>
  /// The actual dollar amount of tax charged, computed once and stored for the same reason as
  /// <see cref="DiscountAmount"/>.
  /// </summary>
  public decimal TaxAmount { get; set; }

  /// <summary>
  /// The final amount charged: Subtotal - DiscountAmount + TaxAmount.
  /// </summary>
  public decimal Total { get; set; }

  /// <summary>
  /// How the customer paid. Nullable since it might not always be recorded.
  /// </summary>
  public PaymentMethod? PaymentMethod { get; set; }

  /// <summary>
  /// The sale's lifecycle state. See <see cref="Enums.Sales.SaleStatus"/> for what each value
  /// means and when inventory actually gets consumed.
  /// </summary>
  public SaleStatus Status { get; set; }

  /// <summary>
  /// UTC timestamp set by the database when this row was first inserted.
  /// </summary>
  public DateTimeOffset CreatedAt { get; set; }

  /// <summary>
  /// UTC timestamp set by the database on insert and advanced on every subsequent update.
  /// </summary>
  public DateTimeOffset UpdatedAt { get; set; }

  /// <summary>
  /// UTC timestamp of a soft delete -- the row itself removed entirely. A different and more
  /// drastic action than setting <see cref="Status"/> to Voided.
  /// </summary>
  public DateTimeOffset? DeletedAt { get; set; }
}
